# Corrected public reference folding controls. No candidates or sequence generation.
import os,sys,subprocess,pathlib,time,json,hashlib,zipfile,base64,io,importlib.util
root=pathlib.Path('/kaggle/working/corrected_controls');root.mkdir(exist_ok=True)
def stage(name,cmd):
 print('STAGE_START',name,time.time(),flush=True)
 with open(root/(name+'.log'),'w')as f:
  q=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
  for line in q.stdout:f.write(line);f.flush();print(line,end='',flush=True)
  rc=q.wait()
 print('STAGE_EXIT',name,rc,flush=True)
 if rc:raise RuntimeError(name+' exit '+str(rc))
try:
 stage('install',[sys.executable,'-m','pip','install','-q','boltzgen==0.3.2'])
 stage('uninstall',[sys.executable,'-m','pip','uninstall','-y','torchvision','torchaudio','torchcodec'])
 from importlib.metadata import version
 from huggingface_hub import hf_hub_download
 print('INSTALLED_VERSIONS',{x:version(x)for x in ['boltzgen','torch','numpy']},flush=True)
 pkg=pathlib.Path(importlib.util.find_spec('boltzgen').origin).parent
 names=['task/predict/data_from_generated.py','data/feature/featurizer.py','data/parse/mmcif.py','task/analyze/analyze_utils.py','task/predict/writer.py']
 hashes={n:hashlib.sha256((pkg/n).read_bytes()).hexdigest()for n in names}
 (root/'installed_source_hashes.json').write_text(json.dumps(hashes,indent=2))
 s=(pkg/names[0]).read_text();assert 'msa={}'in s and 'mmseqs'not in s and 'msa_server'not in s
 print('LOCAL_MSA_EMPTY_VERIFIED',flush=True)
 with zipfile.ZipFile(io.BytesIO(base64.b64decode('')))as z:z.extractall('/kaggle/working/corrected_inputs')
 stage('corrected_single_sample',[sys.executable,'/kaggle/working/corrected_inputs/driver.py'])
 print('PREFLIGHT_FINISHED',0,flush=True)
except Exception as e:
 (root/'failure.txt').write_text(repr(e));print('FAILED',repr(e),flush=True)
finally:
 files=[p for p in root.rglob('*')if p.is_file()and p.name!='manifest.json']
 (root/'manifest.json').write_text(json.dumps([{'path':str(p.relative_to(root)),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}for p in files],indent=2))
 with zipfile.ZipFile('/kaggle/working/CORRECTED_SINGLE_SAMPLE_CONTROL.zip','w',zipfile.ZIP_DEFLATED)as z:
  for p in root.rglob('*'):
   if p.is_file():z.write(p,p.relative_to(root))
 print('ALL_OUTPUTS_PRESERVED',flush=True)